import{_ as a,o as i,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"आवास-गारंटी कानून","description":"","frontmatter":{},"headers":[],"relativePath":"hi/0045-住房保障法.md","filePath":"hi/0045-住房保障法.md"}'),d={name:"hi/0045-住房保障法.md"};function e(o,t,n,h,s,u){return i(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="आवास-गारंटी-कानून" tabindex="-1">आवास-गारंटी कानून <a class="header-anchor" href="#आवास-गारंटी-कानून" aria-label="Permalink to &quot;आवास-गारंटी कानून&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>45</td></tr><tr><td>मॉड्यूल</td><td>कानूनी प्रणाली और शासन-ढाँचा</td></tr><tr><td>कीवर्ड</td><td>निवास-अधिकार, गारंटी आवास, स्थान-न्यायिक सिद्धांत, रहने-योग्य वातावरण, सट्टेबाज़ी-विरोध</td></tr></tbody></table><h2 id="i-विधायी-उद्देश्य-और-मूल-सिद्धांत" tabindex="-1">I. विधायी उद्देश्य और मूल सिद्धांत <a class="header-anchor" href="#i-विधायी-उद्देश्य-और-मूल-सिद्धांत" aria-label="Permalink to &quot;I. विधायी उद्देश्य और मूल सिद्धांत&quot;">​</a></h2><p><em>आवास-गारंटी कानून</em> लंगर सहजीवी सभ्यता के पाँच सहायक कानूनों में से एक है। इसका उद्देश्य हेंग-ब्रह्मांड के भीतर सभी जीवनों के निवास-अधिकार की गारंटी, निष्पक्ष और सतत आवास-गारंटी प्रणाली स्थापित करना, स्थान-न्यायिक सिद्धांत-प्रेषण तकनीक से सभी जातियों के लिए उपयुक्त निवास-स्थान प्रदान करना, तथा आवास-क्षेत्र में सट्टेबाज़ी और शिकार को रोकना है।</p><p>यह कानून निम्न मूल सिद्धांत स्थापित करता है:</p><table tabindex="0"><thead><tr><th>सिद्धांत</th><th>अर्थ</th></tr></thead><tbody><tr><td>निवास-गारंटी</td><td>प्रत्येक जीवन को उपयुक्त निवास-स्थान पाने का अधिकार; राज्य और सभ्यता पर मूल निवास-आवश्यकताएँ पूरी करने का दायित्व</td></tr><tr><td>जनहित-प्राथमिकता</td><td>आवास सर्वप्रथम जीवन-आवश्यकता है, सट्टेबाज़ी की वस्तु नहीं; गारंटी आवास का जनहित-गुण है</td></tr><tr><td>स्थान-दक्षता</td><td>स्थान-न्यायिक सिद्धांत-प्रेषण तकनीक से स्थान-उपयोग क्षमता बढ़ाना, रहने-योग्य स्थान विस्तारित करना</td></tr><tr><td>अन्य-जाति अनुकूलन</td><td>विभिन्न जातियों की शारीरिक विशेषताओं और जीवन-आदतों हेतु अनुकूलित निवास-स्थान प्रदान करना</td></tr><tr><td>रहने-योग्य वातावरण</td><td>निवास-स्थान में अच्छा पारिस्थितिक वातावरण, बुनियादी ढाँचा और सार्वजनिक सेवाएँ होनी चाहिए</td></tr><tr><td>सट्टेबाज़ी-विरोध</td><td>आवास को लक्ष्य बनाकर सट्टेबाज़ी निषिद्ध; आवास को संपत्ति-लूट का साधन बनने से रोकना</td></tr></tbody></table><h2 id="ii-निवास-अधिकार-की-कानूनी-गारंटी" tabindex="-1">II. निवास-अधिकार की कानूनी गारंटी <a class="header-anchor" href="#ii-निवास-अधिकार-की-कानूनी-गारंटी" aria-label="Permalink to &quot;II. निवास-अधिकार की कानूनी गारंटी&quot;">​</a></h2><p>यह कानून स्पष्ट करता है कि निवास-अधिकार सहजीवी संविधान द्वारा प्रत्येक जीवन को प्रदत्त मूल अधिकार है, जिसमें विशेष रूप से शामिल:</p><ol><li><strong>मूल निवास-अधिकार</strong>: प्रत्येक जीवन को न्यूनतम मानक से कम न होने वाला निवास-स्थान पाने का अधिकार; न्यूनतम मानक जाति के शरीर-आकार और जीवन-आवश्यकताओं के अनुसार निर्धारित।</li><li><strong>गारंटी आवास आवेदन-अधिकार</strong>: पात्र जीवनों को गारंटी आवास हेतु आवेदन करने का अधिकार; आवेदन-शर्तें और वितरण-मानक खुले और पारदर्शी।</li><li><strong>निवास-सुरक्षा अधिकार</strong>: निवास-स्थान सुरक्षा-मानकों के अनुरूप होने चाहिए; जर्जर भवन और अनुपयुक्त स्थान किराए या वितरण पर नहीं दिए जा सकते।</li><li><strong>निवास-स्थिरता अधिकार</strong>: गारंटी आवास के निवासी शर्तें पूरी होने पर स्थिर निवास-अधिकार पाते हैं; मनमाने ढंग से बेदखल नहीं किए जा सकते।</li><li><strong>निवास-वातावरण अधिकार</strong>: निवासियों को स्वच्छ वायु, जल-स्रोत और अच्छा आस-पास का वातावरण पाने का अधिकार; पर्यावरण-प्रदूषण पर शिकायत का अधिकार।</li><li><strong>आवास-नवीकरण अधिकार</strong>: निवासियों को भवन-सुरक्षा और अन्यों के अधिकारों को प्रभावित किए बिना निवास-स्थान का उचित नवीकरण करने का अधिकार।</li></ol><h2 id="iii-आवास-गारंटी-प्रणाली" tabindex="-1">III. आवास-गारंटी प्रणाली <a class="header-anchor" href="#iii-आवास-गारंटी-प्रणाली" aria-label="Permalink to &quot;III. आवास-गारंटी प्रणाली&quot;">​</a></h2><p>लंगर सहजीवी सभ्यता की आवास-गारंटी प्रणाली तीन प्रकार के आवासों में विभाजित है, विभिन्न आवश्यकता-स्तरों को आच्छादित करती है:</p><table tabindex="0"><thead><tr><th>प्रकार</th><th>नाम</th><th>गारंटी-विषय</th><th>वितरण-विधि</th><th>किराया/मूल्य</th></tr></thead><tbody><tr><td>प्रथम प्रकार</td><td>सार्वजनिक किराये आवास</td><td>निम्न-आय समूह, प्रारंभिक साधक, नए प्रवासी</td><td>आवेदन-सत्यापन प्रणाली, पंक्ति-वितरण</td><td>प्रतीकात्मक कम किराया</td></tr><tr><td>द्वितीय प्रकार</td><td>साझा-स्वामित्व आवास</td><td>मध्यम-आय समूह, मध्यम साधक</td><td>आवेदन-सत्यापन प्रणाली, लॉटरी-वितरण</td><td>बाज़ार मूल्य से कम; व्यक्ति-राज्य साझा स्वामित्व</td></tr><tr><td>तृतीय प्रकार</td><td>वाणिज्यिक आवास</td><td>उच्च-आय समूह, उच्च साधक</td><td>बाज़ार लेनदेन</td><td>बाज़ार मूल्य, नियंत्रण के अधीन</td></tr></tbody></table><p>इसके अतिरिक्त, स्थान-न्यायिक सिद्धांत-प्रेषण तकनीक से &quot;संवलित-स्थान निवास-क्षेत्र&quot; बनाए जाते हैं: सीमित भौतिक स्थान में स्थान-संवलन तकनीक से निवास-क्षेत्रफल बढ़ाना, उच्च-घनत्व क्षेत्रों को अधिक निवास-स्थान देना। संवलित-स्थान निवास-क्षेत्रों को सुरक्षा-मूल्यांकन से गुजरना अनिवार्य है, ताकि स्थान-स्थिरता सुनिश्चित हो।</p><h2 id="iv-अन्य-जातियों-के-लिए-आवास-अनुकूलन" tabindex="-1">IV. अन्य-जातियों के लिए आवास अनुकूलन <a class="header-anchor" href="#iv-अन्य-जातियों-के-लिए-आवास-अनुकूलन" aria-label="Permalink to &quot;IV. अन्य-जातियों के लिए आवास अनुकूलन&quot;">​</a></h2><p>हेंग-ब्रह्मांड के भीतर विभिन्न जातियों की विशेष निवास-आवश्यकताओं के अनुरूप, यह कानून अन्य-जाति आवास-अनुकूलन व्यवस्था स्थापित करता है:</p><ul><li><strong>जल-जातियाँ</strong>: पानी के नीचे निवास-स्थान या जल-थल द्विजीवी निवास, जल-संचार और जल-गुणवत्ता रखरखाव प्रणालियों से युक्त।</li><li><strong>उड़ान-जातियाँ</strong>: उच्च-ऊँचाई निवास-स्थान या उड़ान-अवतरण मंच वाले निवास, वायु-यातायात प्रबंधन से युक्त।</li><li><strong>ऊर्जा-जीवन</strong>: उपयुक्त ऊर्जा-सांद्रता वाले निवास-स्थान, ऊर्जा-स्थिरीकरण उपकरणों से युक्त।</li><li><strong>विशाल-जातियाँ</strong>: बड़े पैमाने के निवास-स्थान, विशेष सुदृढ़ीकृत भवन-संरचनाओं के साथ।</li><li><strong>सूक्ष्म-जातियाँ</strong>: सूक्ष्म निवास-क्षेत्र, स्केलिंग-मार्ग और विशेष सुविधाओं से युक्त।</li></ul><p>अन्य-जाति आवास-अनुकूलन मानक आवास-प्रशासन विभाग द्वारा सभी जातियों के प्रतिनिधियों के साथ संयुक्त रूप से निर्धारित और नियमित रूप से अद्यतन किए जाते हैं।</p><h2 id="v-आवास-निर्माण-और-प्रबंधन" tabindex="-1">V. आवास-निर्माण और प्रबंधन <a class="header-anchor" href="#v-आवास-निर्माण-और-प्रबंधन" aria-label="Permalink to &quot;V. आवास-निर्माण और प्रबंधन&quot;">​</a></h2><ul><li><strong>आवास-निर्माण योजना</strong>: राज्य जनसंख्या-वृद्धि और प्रवासन के अनुसार आवास-निर्माण योजनाएँ बनाता है, आपूर्ति-माँग संतुलन सुनिश्चित करता है।</li><li><strong>निर्माण-मानक</strong>: गारंटी आवास का निर्माण सुरक्षा, पर्यावरण-अनुकूलता, रहने-योग्यता मानकों के अनुरूप अनिवार्य; निर्माण-गुणवत्ता घटाना निषिद्ध।</li><li><strong>संपत्ति-प्रबंधन</strong>: निवास-क्षेत्र स्वायत्त-प्रबंधन और व्यावसायिक संपत्ति-सेवाओं के संयुक्त मॉडल लागू करते हैं; निवासियों को संपत्ति-प्रबंधन निर्णयों में भाग लेने का अधिकार।</li><li><strong>आवास-मरम्मत</strong>: गारंटी आवास की मरम्मत आवास-प्रबंधन संस्था की ज़िम्मेदारी; मरम्मत-कोष सार्वजनिक संचय से।</li><li><strong>निकास तंत्र</strong>: गारंटी आवास के निवासियों की आय या साधना गारंटी-मानक से अधिक होने पर उन्हें गारंटी आवास छोड़ना या वाणिज्यिक आवास में बदलना होगा; निकास के लिए उचित संक्रमण-अवधि दी जाती है।</li></ul><h2 id="vi-सट्टेबाज़ी-विरोध-और-निगरानी" tabindex="-1">VI. सट्टेबाज़ी-विरोध और निगरानी <a class="header-anchor" href="#vi-सट्टेबाज़ी-विरोध-और-निगरानी" aria-label="Permalink to &quot;VI. सट्टेबाज़ी-विरोध और निगरानी&quot;">​</a></h2><p>आवास-क्षेत्र में सट्टेबाज़ी और शिकार रोकने के लिए, यह कानून निम्न निगरानी-उपाय स्थापित करता है:</p><ol><li>व्यक्ति के पास वाणिज्यिक आवास की संख्या सीमित करना; सीमा से अधिक पर प्रगतिशील संपत्ति-कर वसूलना।</li><li>गारंटी आवास की उप-किराये और पुनर्विक्रय निषिद्ध; उल्लंघनकर्ताओं की गारंटी-पात्रता निरस्त और आवास वापस।</li><li>आवास-लेनदेन सूचना-प्रकटीकरण प्रणाली स्थापित करना, पर्दे के पीछे की कार्रवाइयों और मूल्य-हेरफेर को रोकना।</li><li>रियल-एस्टेट डेवलपर्स पर योग्यता-प्रबंधन और कोष-निगरानी लागू करना, अधूरी परियोजनाओं और धोखाधड़ी को रोकना।</li><li>आवास-शिकायत और विवाद-समाधान तंत्र स्थापित करना, निवासियों के वैध अधिकारों की रक्षा।</li></ol><h2 id="vii-कानूनी-दायित्व" tabindex="-1">VII. कानूनी दायित्व <a class="header-anchor" href="#vii-कानूनी-दायित्व" aria-label="Permalink to &quot;VII. कानूनी दायित्व&quot;">​</a></h2><p>इस कानून के प्रावधानों का उल्लंघन करने वाले कृत्य परिस्थितियों की गंभीरता के अनुसार निम्न दायित्व वहन करते हैं:</p><ul><li>नियम-विरुद्ध गारंटी आवास वितरण पर सुधार-आदेश और जिम्मेदार व्यक्तियों पर दंड।</li><li>गारंटी आवास की उप-किराये या पुनर्विक्रय पर गारंटी-पात्रता निरस्त, आवास वापस और जुर्माना।</li><li>निर्माण-गुणवत्ता घटाने वाले डेवलपर्स पर पुनर्निर्माण-आदेश और जुर्माना; गंभीर परिस्थितियों में योग्यता निरस्त।</li><li>आवास-सट्टेबाज़ी पर उच्च सट्टा-कर और जुर्माना।</li><li>जर्जर भवन किराए पर देकर निवासियों को हानि पहुँचाने पर क्षतिपूर्ति-दायित्व; गंभीर परिस्थितियों में आपराधिक दायित्व।</li></ul><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p><em>आवास-गारंटी कानून</em> लंगर सहजीवी सभ्यता की &quot;हर किसी के लिए मार्ग&quot; दर्शन की निवास-क्षेत्र में प्राप्ति है। वर्गीकृत आवास-गारंटी प्रणाली स्थापित करके, स्थान-न्यायिक तकनीक से निवास-स्थान विस्तारित करके, अन्य-जाति निवास-आवश्यकताओं का अनुकूलन करके, आवास-सट्टेबाज़ी से लड़कर यह सुनिश्चित करता है कि प्रत्येक जीवन को सुरक्षित, उपयुक्त, स्थिर घर मिले, दस हजार जातियों के साझा उन्नयन के लिए सुखद-निवास गारंटी प्रदान करता है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>40-共生宪法总纲 (सहजीवी संविधान: सामान्य सिद्धांत)</li><li>39-住房与环境保障 (आवास और पर्यावरण संरक्षण)</li><li>13-空间法理调度体系详解 (स्थान-न्यायिक सिद्धांत-प्रेषण प्रणाली का विस्तृत विवरण)</li><li>46-环境保护法 (पर्यावरण संरक्षण कानून)</li></ul>',29)])])}const g=a(d,[["render",e]]);export{c as __pageData,g as default};
